INSERT INTO route_neighborhoods (route_id, order_index, neighborhood_name)
SELECT id, v.order_index, v.neighborhood_name
  FROM routes,
       (VALUES (0, 'Terminal de transportes'),
               (1, 'Centro comercial avenida'),
               (2, 'Avenida Las Palmas'),
               (3, 'Paradero Filipo'),
               (4, 'Puente del Aguila'),
               (5, 'Clinica Belen'),
               (6, 'Universidad de Cundinamarca'),
               (7, 'Centro Comercial Manila'),
               (8, 'Mr Beef'),
               (9, 'Restaurante Universitario'),
               (10, 'D1 Balmoral'),
               (11, 'Paradero Comuneros')) AS v(order_index, neighborhood_name)
 WHERE name = 'Siboney';

INSERT INTO fares (route_id, amount, reference_point, order_index, valid_from)
SELECT id, 2600, NULL, 0, DATE '2026-02-05'
  FROM routes WHERE name = 'Siboney';
